import yaml, sys
d=yaml.safe_load(sys.stdin)
# Look for context settings
print('=== Context Settings ===')
for key in ['context', 'context_compressor', 'compressor', 'threshold', 'model']:
    if key in d:
        print(f'{key}: {d[key]}')
print()
print('=== All top-level keys ===')
for k in d:
    print(f'  {k}')
" 2>/dev/null", "timeout": 5}

